package main

// The completion files are generated by tools/completions from the option table
// in cli.go, then committed. This test is what keeps them honest: the generator
// parses Go source with a regular expression, so if the table changes shape the
// generator may silently produce less than it should -- and a completion file
// that offers a removed option, or forgets a new one, is worse than none.
//
// It deliberately checks the committed files, not freshly generated ones: the
// point is that what ships in the package matches the program in the package.

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

var completionFiles = []string{"sl.bash", "_sl", "sl.fish"}

func readCompletions(t *testing.T) map[string]string {
	t.Helper()
	out := map[string]string{}
	for _, name := range completionFiles {
		data, err := os.ReadFile(filepath.Join("..", "completions", name))
		if err != nil {
			t.Fatalf("completion file %s: %v (run `make completions`)", name, err)
		}
		out[name] = string(data)
	}
	return out
}

func TestCompletionsMatchOptions(t *testing.T) {
	files := readCompletions(t)

	longs := map[string]bool{}
	shorts := map[string]bool{}
	for _, o := range optionSpecs {
		longs[o.long] = true
		if o.short != 0 {
			shorts[string(o.short)] = true
		}
	}

	// each shell spells a long option its own way
	spelling := func(name, long string) string {
		if name == "sl.fish" {
			return "-l " + long
		}
		return "--" + long
	}
	for name, body := range files {
		if !strings.Contains(body, "generated by tools/completions") {
			t.Errorf("%s: no generation marker; was it edited by hand?", name)
		}
		for long := range longs {
			if !strings.Contains(body, spelling(name, long)) {
				t.Errorf("%s: option --%s is missing", name, long)
			}
		}
	}

	// short flags only make sense in bash and zsh; fish spells them -s x, which
	// the check above on long names already covers indirectly, so check the two
	// shells that use them directly
	for name := range files {
		for short := range shorts {
			want := "-" + short
			if name == "sl.fish" {
				want = "-s " + short
			}
			if !strings.Contains(files[name], want) {
				t.Errorf("%s: short flag -%s is missing", name, short)
			}
		}
	}

	// --color accepts three values; all of them must be offered
	for _, name := range completionFiles {
		for _, v := range []string{"auto", "always", "never"} {
			if !strings.Contains(files[name], v) {
				t.Errorf("%s: --color value %q is not offered", name, v)
			}
		}
	}
}

// TestCompletionsKnowEveryGroup: the group names are the one list in the
// completion files that does not come from the option table, so it is checked
// against the program's own groupNames().
func TestCompletionsKnowEveryGroup(t *testing.T) {
	files := readCompletions(t)
	for _, g := range groupNames() {
		if g == "file" || g == "other" {
			continue // covered by the same list; nothing special to check
		}
		for name, body := range files {
			if !strings.Contains(body, g) {
				t.Errorf("%s: group %q is missing from the rule completion", name, g)
			}
		}
	}
}

// TestCompletionsCarryDescriptions: every option's help text must reach the
// shells that can show it. zsh puts it in brackets after the option name and
// fish after -d; bash cannot display descriptions at all, so it is exempt.
func TestCompletionsCarryDescriptions(t *testing.T) {
	files := readCompletions(t)

	// Same escaping the generator applies, kept here on purpose: if the shape
	// of a spec changes, this test is what says so.
	zshEscape := func(s string) string {
		s = strings.ReplaceAll(s, `\`, `\\`)
		s = strings.ReplaceAll(s, "[", `\[`)
		s = strings.ReplaceAll(s, "]", `\]`)
		s = strings.ReplaceAll(s, ":", `\:`)
		return strings.ReplaceAll(s, "'", `'\''`)
	}
	fishEscape := func(s string) string {
		s = strings.ReplaceAll(s, `\`, `\\`)
		return strings.ReplaceAll(s, "'", `\'`)
	}

	for _, o := range optionSpecs {
		if o.help == "" {
			t.Errorf("--%s has no help text, so no shell can describe it", o.long)
			continue
		}
		if !strings.Contains(files["_sl"], zshEscape(o.help)) {
			t.Errorf("_sl does not describe --%s: want %q", o.long, o.help)
		}
		if !strings.Contains(files["sl.fish"], "-d '"+fishEscape(o.help)+"'") {
			t.Errorf("sl.fish does not describe --%s: want %q", o.long, o.help)
		}
	}
}
